 r=get(f,m);rows.append(accepted(r,fam,trigger,inputs,outputs,obs,limits+' 固定官方61292848b81ee4a7a33443beb52aabdc446355b8源码静态研究；未运行上游或本项目游戏/服务器。不等同Dynasty存档实测；Colony仅读载入/写出接线片段，不声称全文审大型Colony。',support(files,r)))
